/* N/query mock for the custom field setup links. customfield and customsegment answer as on the sandbox:
 * script IDs are stored upper case, customfield gives id + fieldtype (BODY, COLUMN, ...), customsegment
 * gives internalid. Every query is logged in window.__suiteql as [sql, params].
 * ?cffail=1: the role may not read custom field definitions, so the query is rejected.
 * ?cffail=2: only customfield is refused, with the error a role without access got on a real account; customsegment works. */
(function () {
  var FIELDS = {
    CUSTBODY_TAGS: [101, 'BODY'], CUSTBODY_QUOTE: [103, 'BODY'], CUSTBODY_EMPTY: [104, 'BODY'],
    /* A type with no setup page the explorer knows: no link. */
    CUSTBODY_ADJ: [108, 'WORKFLOW'],
    CUSTCOL_A: [202, 'COLUMN'],
    CUSTBODY_SECRET: [105, 'BODY'], CUSTBODY_APPROVER: [107, 'BODY']
  };
  var SEGMENTS = { CSEG1: 7 };
  var fail = /[?&]cffail=1/.test(location.search), failFields = /[?&]cffail=2/.test(location.search);
  window.__suiteql = [];
  function result(rows) { return { asMappedResults: function () { return rows; } }; }
  window.__nsQuery = {
    runSuiteQL: {
      promise: function (o) {
        window.__suiteql.push([o.query, (o.params || []).slice()]);
        if (fail) return Promise.reject({ name: 'SSS_PERMISSION_VIOLATION', message: 'You need the Custom Fields permission' });
        if (failFields && /FROM customfield/i.test(o.query)) return Promise.reject({ name: 'SSS_SEARCH_ERROR_OCCURRED', message: "Search error occurred: Record 'customfield' was not found." });
        var rows = [];
        if (/FROM customfield/i.test(o.query)) (o.params || []).forEach(function (p) { var f = FIELDS[p]; if (f) rows.push({ id: f[0], scriptid: p, fieldtype: f[1] }); });
        else if (/FROM customsegment/i.test(o.query)) (o.params || []).forEach(function (p) { if (SEGMENTS[p]) rows.push({ internalid: SEGMENTS[p], scriptid: p }); });
        return new Promise(function (res) {
          function answer() { setTimeout(function () { res(result(rows)); }, 20); }
          if (window.__cfHold) window.__cfWaiting.push(answer); else answer();
        });
      }
    }
  };
  /* window.__cfHold = true holds every answer until window.__cfRelease() (a test can then make the render the
   * answer causes land at a moment of its choosing, for example in the middle of a drag). */
  window.__cfWaiting = [];
  window.__cfRelease = function () { window.__cfHold = false; window.__cfWaiting.splice(0).forEach(function (f) { f(); }); };
})();

